@extends('layouts.app') @section('page-title','Insurance Claims') @section('content')<div class="dashboard-grid align-start"><section class="panel"><h2>Submit claim</h2><form method="post" action="{{ route('staff.insurance.store') }}">@csrf<label>Invoice<select name="invoice_id">@foreach($invoices as $i)<option value="{{ $i->invoice_id }}">{{ $i->invoice_no }} · {{ $i->patient->full_name }} · Rs. {{ $i->balance_amount }}</option>@endforeach</select></label><label>Provider<select name="provider_id">@foreach($providers as $p)<option value="{{ $p->provider_id }}">{{ $p->provider_name }}</option>@endforeach</select></label><label>Policy number<input name="policy_no" required></label><label>Requested amount<input type="number" name="requested_amount" min="0.01" step="0.01" required></label><button class="btn btn-primary">Submit claim</button></form></section><section><h2>Claims</h2>@forelse($claims as $c)<article class="panel"><div class="panel-head"><div><span class="kicker">{{ $c->claim_no }}</span><h3>{{ $c->invoice->patient->full_name }}</h3><p>{{ $c->provider->provider_name }}</p></div><x-status :value="$c->status"/></div>@if(in_array($c->status,['APPROVED','REJECTED','CANCELLED'],true))<div class="summary-box"><strong>Finalized claim</strong><p>Requested: Rs. {{ number_format($c->requested_amount,2) }} · Approved: Rs. {{ number_format($c->approved_amount,2) }}</p>@if($c->notes)<small>{{ $c->notes }}</small>@endif</div>@else<form method="post" action="{{ route('staff.insurance.update',$c) }}">@csrf<div class="form-grid"><label>Status<select name="status">@foreach(['PENDING','SUBMITTED','MORE_INFO','APPROVED','REJECTED','CANCELLED'] as $v)<option value="{{ $v }}" @selected($c->status===$v)>{{ str_replace('_',' ',$v) }}</option>@endforeach</select></label><label>Approved amount<input type="number" min="0.01" max="{{ $c->requested_amount }}" step="0.01" name="approved_amount" value="{{ $c->approved_amount ?: '' }}" placeholder="Required for approval"></label><label class="span-2">Notes<input name="notes" maxlength="500" value="{{ $c->notes }}"></label></div><button class="btn btn-secondary btn-sm">Update claim</button></form>@endif</article>@empty<x-empty title="No claims"/>@endforelse{{ $claims->links() }}</section></div>@endsection